const input=(id,type,value)=>{const control=node('input');control.id=id;control.type=type;if(value!==undefined)control.value=value;return control;};
const select=(id,options)=>{const control=node('select');control.id=id;for(const [value,text]of options){const option=node('option','',text);option.value=value;control.append(option);}return control;};
