 function releasePlayer(id){const player=players.get(id);if(!player)return;player.element.pause();player.element.removeAttribute('src');player.element.load();URL.revokeObjectURL(player.url);players.delete(id);}
 function hidePlayer(){playerSerial++;if(selectedPlayer)players.get(selectedPlayer)?.element.pause();selectedPlayer='';playerPanel.hidden=true;playerHolder.replaceChildren();}
 async function preview(id){const sequence=++playerSerial,video=await engine.getVideo(id);if(!video||sequence!==playerSerial)return;let player=players.get(id);if(player&&player.blob!==video.blob){releasePlayer(id);player=null;}if(!player){const element=node('video');element.controls=true;element.playsInline=true;element.preload='metadata';element.dataset.multiPreview=id;const url=URL.createObjectURL(video.blob);element.src=url;player={element,url,blob:video.blob,progressed:false};players.set(id,player);element.addEventListener('timeupdate',()=>{if(!element.paused&&!element.seeking&&element.currentTime>.05){player.progressed=true;if(selectedPlayer===id)played.disabled=busy();}});}if(selectedPlayer&&selectedPlayer!==id)players.get(selectedPlayer)?.element.pause();selectedPlayer=id;playerHolder.replaceChildren(player.element);playerTitle.textContent=video.title;playerPanel.hidden=false;played.checked=Boolean(state.jobs.find(job=>job.id===id)?.videoReviewed);played.disabled=busy()||!player.progressed&&!played.checked;playerPanel.scrollIntoView({block:'start'});}
 async function loadThumbnail(id,img){const value=await engine.getThumbnail(id);if(!value)return;let cached=thumbnailUrls.get(id);if(!cached||cached.blob!==value.blob){if(cached)URL.revokeObjectURL(cached.url);cached={blob:value.blob,url:URL.createObjectURL(value.blob)};thumbnailUrls.set(id,cached);}if(img.isConnected)img.src=cached.url;}
 function jobAction(id,text,data,action){const control=button('',text);control.dataset[data]=id;control.disabled=busy();control.addEventListener('click',perform(action));return control;}
